coachView.loadJsFunction:
setTimeout(() => {
	this.initalizer();
}, 500);
var requestType=this.context.binding.get("value").get("requestType");
var productCode=this.context.options.productCode.get("value");
var operationCode=this.context.binding.get("value").get("oldOperationType");
var finalOperation = productCode+"-"+requestType+"-"+operationCode;
const productcode = {

	change: ["OUBC", "OSBC","OMBC" ]
};
 const shouldEnable = productcode.change.includes(productCode);
this.context.options.operationcode.set("value", finalOperation) ;
if (requestType=="amend") {
	this.ui.get("paymentTerms").setEnabled(false);
	
}
if (requestType=="amend" && shouldEnable && operationCode=="COL") {
this.ui.get("operationType").setEnabled(true);
}

inlineScript.scriptBlock:
// control visibility of dates on contract creation - on change of payment terms.
this.setPaymentTermsVis = function (me, isChange) {
	if (!isChange) me.setEnabled(this.isMaker && !this.isReqAmend);

	// control vis related to payment terms
	var isMultiTenor = me.getData().name == "004" || false;

	if (!this.maturityDate || !this.tenorDays || !this.transitDays) {
		this.initalizer();
	}

	if (this.maturityDate && this.tenorDays && this.transitDays) {
		// replace true with !isMultiTenor (after uat)
		this.transitDays.setEnabled(this.isMaker);
		this.tenorDays.setEnabled(this.isMaker);
		this.maturityDate.setEnabled(this.isMaker);
	}
};

this.setFoMaturity1 = function (value) {
	var tabs = this.ui.getAbsoluteName().split("/");
	// remove the last part of the path
	tabs.pop();
	// add 4 as the last part of the path (FO Index)
	tabs.push("4");
	var fo = bpmext.ui.getView(tabs.join("/"));
	// var fo = bpmext.ui.getView("/DC_Templete1/4");
	if (fo) {
		fo.maturityDate(value);
	}
};

//----------------------------------------------------------------------------------------
//Set Validation on Bills & Invoices - check if bill/invoice exist before for the same cif
var bill = {};
this.checkBill = function (value) {
	bill = value;
	var input = bill.getData() + "-" + this.context.options.cif.get("value");
	this.ui.get("SC_checkBill0").execute(input);
};

this.setBillValidation = function () {
	if (this.context.options.billExist.get("value") == 1) {
		this.context.options.IsBillExist.set("value", true);
		bill.setValid(false, "WARNING : This Bill Is Used Before In Another Request");
	} else {
		this.context.options.IsBillExist.set("value", false);
		bill.setValid(true);
	}
};

var invoice = {};
this.checkInvoice = function (value) {
	invoice = value;
	var input = invoice.getData() + "-" + this.context.options.cif.get("value");
	this.ui.get("SC_checkInvoice0").execute(input);
};
this.setInvoiceValidation = function () {
	// console.log("Out---------");
	if (this.context.options.invoiceExist.get("value") == 1) {
		this.context.options.IsInvoiceExist.set("value", true);
		invoice.setValid(false, "WARNING : This Invoice Is Used Before In Another Request");
	} else {
		this.context.options.IsInvoiceExist.set("value", false);
		invoice.setValid(true);
	}
};

//--------------error handling------------------
this.AjaxErrorHandling = function (errorMSG) {
	this.context.options.alertMessage.set("value", errorMSG);
	this.context.options.errorVis.set("value", "EDITABLE");
};
var disable = this.context.options.disable.get("value");

//show latest flexcube contract numbers
this.showLatestContractNumber = function (me) {

//	var isCollection = this.context.binding.get("value").get("requestType").toLowerCase().includes("collection");
//	var isAmend = this.context.binding.get("value").get("requestType").toLowerCase().includes("amend");
//	var isRecreate = this.context.binding.get("value").get("requestType").toLowerCase().includes("recreate");
	var isUpdate = this.context.binding.get("value").get("requestNature").toLowerCase().includes("update");
	if (isUpdate && !!me.getData()) {
		me.setVisible(true);
		me.setEnabled(false);
	}else{
		me.setVisible(false, true);
	}
};

// initialize needed objects and views 
this.initalizer = function () { 
	this.isReqAmend = this.context.binding.get("value").get("requestType").toLowerCase().includes("amend") || false;
	this.isMaker = this.context.options.basicDetailsCVVIS.get("value").toLowerCase() == "editable" || false;

	this.transitDays = this.getViewByPath("/DC_Templete1/7/transitDays");
	this.tenorDays = this.getViewByPath("/DC_Templete1/7/tenorDays");
	this.maturityDate = this.getViewByPath("/DC_Templete1/7/maturityDate");
}

this.getViewByPath = function (path) {
	return bpmext.ui.getView(path) || null;
};

// reusable function to prevent negative value on input (only works on input not on change)
this.preventNegativeInput = function (me) {
	// Add an event listener to the input field of the Integer control
	me.context.element.addEventListener("input", function (event) {
		// Get the current value of the input
		var currentValue = event.target.value;

		// If the value starts with a '-' prevent it
		if (currentValue.startsWith("-")) {
			event.target.value = currentValue.replace("-", "");
		}
	});
};


this.testInstanceID = function(){
	var inId = this.context.bpm.system.instanceId;
	this.ui.get("Service_Call1").execute(inId);
}
var operation = this.context.binding.get("value").get("operationType").get("value");
this.setOperationCode = function () {
		var obj = {};
		obj.name=operation;
		obj.value = operation;
		this.ui.get("OperationType").setData(obj);
		
};
